/* ═══════════ ١٥) الوراثة المندلية ═══════════ */
function gMono(){
  var p=gp([
    ["Aa","Aa","3 : 1 (سائد : متنحّي)","1 : 2 : 1 (AA : Aa : aa)","75٪","25٪"],
    ["Aa","aa","1 : 1 (سائد : متنحّي)","0 : 1 : 1 (AA : Aa : aa)","50٪","50٪"],
    ["AA","aa","الكلُّ سائد (100٪)","الكلُّ Aa","100٪","0٪"],
    ["AA","Aa","الكلُّ سائد (100٪)","1 : 1 (AA : Aa)","100٪","0٪"],
    ["aa","aa","الكلُّ متنحّي (100٪)","الكلُّ aa","0٪","100٪"]
  ]);
  var ask=gp(["pheno","geno","pctDom","pctRec"]);
  if(ask==="pheno") return Q('عند تهجين '+p[0]+' × '+p[1]+'، ما نسبةُ الطُّرُز الشكليّة في النسل؟',
    p[2], ['3 : 1 (سائد : متنحّي)','1 : 1 (سائد : متنحّي)','الكلُّ سائد (100٪)','الكلُّ متنحّي (100٪)','9 : 3 : 3 : 1'],
    'نرسم مربّعَ بانيت لـ'+p[0]+' × '+p[1]+' ⇐ الطُّرُزُ الشكليّة '+p[2]+'. (والطرازُ الشكليُّ هو الصفةُ الظاهرة، والجينيُّ هو تركيبُ الأليلات.)');
  if(ask==="geno") return Q('عند تهجين '+p[0]+' × '+p[1]+'، ما نسبةُ الطُّرُز الجينيّة في النسل؟',
    p[3], ['1 : 2 : 1 (AA : Aa : aa)','0 : 1 : 1 (AA : Aa : aa)','الكلُّ Aa','1 : 1 (AA : Aa)','الكلُّ aa'],
    'من مربّع بانيت لـ'+p[0]+' × '+p[1]+' ⇐ الطُّرُزُ الجينيّة '+p[3]+'.');
  if(ask==="pctDom") return Q('عند تهجين '+p[0]+' × '+p[1]+'، ما النسبةُ المئويّةُ للأفراد التي تظهر عليها الصفةُ السائدة؟',
    p[4], ['25٪','50٪','75٪','100٪','0٪'],
    'الصفةُ السائدةُ تظهر إذا وُجد أليلٌ سائدٌ واحدٌ على الأقلّ ⇐ '+p[4]+' في تهجين '+p[0]+' × '+p[1]+'.');
  return Q('عند تهجين '+p[0]+' × '+p[1]+'، ما النسبةُ المئويّةُ للأفراد التي تظهر عليها الصفةُ المتنحّية؟',
    p[5], ['25٪','50٪','75٪','100٪','0٪'],
    'الصفةُ المتنحّيةُ لا تظهر إلّا في الحالة المتماثلةِ المتنحّية (aa) ⇐ '+p[5]+'.');
}
function gGametes(){
  var g=gp([["AA",1,"مشيجٌ واحدٌ (A)"],["Aa",2,"مشيجان (A و a)"],["AABB",1,"مشيجٌ واحدٌ (AB)"],["AaBB",2,"مشيجان (AB و aB)"],["AaBb",4,"أربعةُ أمشاجٍ (AB و Ab و aB و ab)"],["AaBbCc",8,"ثمانيةُ أمشاج"]]);
  return Q('كم نوعًا من الأمشاج يُنتِج الفردُ الذي طرازُه الجينيّ '+g[0]+' ؟',
    g[1]+' — '+g[2], ['1 — مشيجٌ واحد','2 — مشيجان','4 — أربعةُ أمشاج','8 — ثمانيةُ أمشاج'].filter(function(x){ return x.indexOf(g[1]+' —')!==0; }),
    'عددُ أنواعِ الأمشاج = 2 مرفوعًا لعددِ الأزواج غيرِ المتماثلة. وفي '+g[0]+' عددُ الأزواج غيرِ المتماثلة '+(Math.log2(g[1]))+' ⇐ '+g[1]+'.');
}
function gGenoType(){
  var p=gp([
    ["متماثلُ الجينات سائد","AA","المتماثلُ السائدُ أليلاه سائدان."],
    ["متماثلُ الجينات متنحّي","aa","المتماثلُ المتنحّي أليلاه متنحّيان، وهو وحدُه تظهر عليه الصفةُ المتنحّية."],
    ["غيرُ متماثلِ الجينات (هجين)","Aa","غيرُ المتماثلِ أليلٌ سائدٌ وأليلٌ متنحّي، وتظهر عليه الصفةُ السائدة."],
    ["متماثلٌ متنحّي لصفتين","aabb","لصفتين: كلُّ زوجٍ متماثلٌ متنحّي."]
  ]);
  return Q('أيُّ الطُّرُز الجينيّة يُعدّ «'+p[0]+'» ؟',
    p[1], ['AA','aa','Aa','aabb','AaBb','SSRR'].filter(function(x){ return x!==p[1]; }),
    p[2]);
}
