/* ═══════════ ١٦) المادة الوراثية DNA ═══════════ */
function gDNA(){
  var ask=gp(["pair","pct","strand"]);
  if(ask==="pair"){
    var b=gp([["الأدينين A","الثايمين T","في DNA يرتبط A مع T برابطتين هيدروجينيّتين"],["الجوانين G","السايتوسين C","يرتبط G مع C بثلاثِ روابطَ هيدروجينيّة"],["السايتوسين C","الجوانين G","يرتبط C مع G بثلاثِ روابط"],["الثايمين T","الأدينين A","يرتبط T مع A برابطتين"]]);
    return Q('في جزيء DNA، مع أيِّ قاعدةٍ يرتبط '+b[0]+' ؟',
      b[1], ['الأدينين A','الثايمين T','الجوانين G','السايتوسين C','اليوراسيل U'].filter(function(x){ return x!==b[1]; }),
      b[2]+' — وقاعدةُ التزاوجِ التكامليّ: A–T و G–C. (وفي RNA يحلّ اليوراسيلُ U محلَّ الثايمين.)');
  }
  if(ask==="pct"){
    var a=gp([10,15,20,25,30,35]);
    var gc=(100-2*a)/2;
    if(gc<=0 || gc!==Math.round(gc)) return null;
    return Q('في جزيء DNA نسبةُ الأدينين A = '+a+'٪. ما نسبةُ الجوانين G ؟',
      gc+'٪', [a+'٪', (100-a)+'٪', (2*a)+'٪'],
      'قاعدةُ شارجاف: A = T و G = C. فإذا كان A = '+a+'٪ فإنّ T = '+a+'٪ ومجموعُهما '+(2*a)+'٪، ويبقى '+(100-2*a)+'٪ لـ G و C بالتساوي ⇐ G = '+gc+'٪.');
  }
  var seq=[], comp=[];
  for(var i=0;i<6;i++){ var c=gp(["A","T","G","C"]); seq.push(c); comp.push({A:"T",T:"A",G:"C",C:"G"}[c]); }
  return Q('ما الشريطُ المكمّل لشريط DNA التالي: '+seq.join("–")+' ؟',
    comp.join("–"), [seq.join("–"), seq.slice().reverse().join("–"), comp.slice().reverse().join("–")],
    'نُقابِل كلَّ قاعدةٍ بمكمّلتها: A↔T و G↔C ⇐ '+comp.join("–")+'.');
}
function gCodon(){
  var aa=gp([2,3,4,5,6,8,10,12]);
  var bases=aa*3;
  var ask=gp(["b2a","a2b"]);
  if(ask==="b2a") return Q('سلسلةُ mRNA فيها '+bases+' قاعدةً نيتروجينيّة. كم حمضًا أمينيًّا تُرمِّز؟',
    aa, [bases, bases/2, aa*3],
    'كلُّ ثلاثِ قواعدَ (كودون) تُرمِّز حمضًا أمينيًّا واحدًا ⇐ '+bases+' ÷ 3 = '+aa+'.');
  return Q('بروتينٌ عددُ أحماضه الأمينيّة '+aa+'. كم قاعدةً نيتروجينيّةً على الأقلّ تلزم لترميزه؟',
    bases, [aa, aa*2, aa*4],
    'كلُّ حمضٍ أمينيٍّ يحتاج كودونًا من ثلاثِ قواعد ⇐ '+aa+' × 3 = '+bases+' قاعدة.');
}
